const projects=JSON.parse(document.getElementById('project-data').textContent);
const dialog=document.getElementById('project-dialog'),frame=document.getElementById('dialog-image'),screen=document.querySelector('.screen'),strip=document.getElementById('filmstrip');
let project,index=0,opener,version=0,start;
function imageAt(i){if(i<0||i>=project.images.length)return;index=i;const image=project.images[i],v=++version;screen.classList.remove('is-entering');frame.src=image.src;frame.alt=image.caption;document.getElementById('image-caption').textContent=image.caption;document.getElementById('image-counter').textContent=`${i+1} / ${project.images.length}`;document.getElementById('previous-image').disabled=i===0;document.getElementById('next-image').disabled=i===project.images.length-1;[...strip.children].forEach((b,n)=>b.setAttribute('aria-current',String(i===n)));frame.decode().catch(()=>{}).then(()=>{if(v===version)screen.classList.add('is-entering')});}
function openProject(button){project=projects.find(p=>p.id===button.dataset.project);if(!project)return;opener=button;document.getElementById('dialog-category').textContent=project.media;for(const [id,val] of [['project-title',project.title],['project-date',project.date],['project-lead',project.lead],['project-role',project.role],['project-scale',project.scale]])document.getElementById(id).textContent=val;const body=document.getElementById('project-body');body.replaceChildren();project.body.forEach(([title,copy])=>{const h=document.createElement('h3'),p=document.createElement('p');h.textContent=title;p.textContent=copy;body.append(h,p)});const link=document.getElementById('project-link');link.hidden=!project.link;if(project.link){link.href=project.link[0];link.textContent=project.link[1]+' ↗'}else link.removeAttribute('href');strip.replaceChildren();project.images.forEach((img,i)=>{const b=document.createElement('button'),im=document.createElement('img');b.type='button';b.setAttribute('aria-label',img.caption);im.src=img.src;im.alt='';b.append(im);b.addEventListener('click',()=>imageAt(i));strip.append(b)});strip.hidden=project.images.length<2;dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;imageAt(Number(button.dataset.slide)||0);document.getElementById('close-dialog').focus({preventScroll:true});}
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>openProject(b)));
document.getElementById('close-dialog').addEventListener('click',()=>dialog.close());document.getElementById('previous-image').addEventListener('click',()=>imageAt(index-1));document.getElementById('next-image').addEventListener('click',()=>imageAt(index+1));dialog.addEventListener('close',()=>{version++;document.body.classList.remove('modal-open');opener?.focus({preventScroll:true})});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();imageAt(index+(e.key==='ArrowRight'?1:-1))}});screen.addEventListener('touchstart',e=>{start=[e.changedTouches[0].clientX,e.changedTouches[0].clientY]},{passive:true});screen.addEventListener('touchend',e=>{if(!start)return;const dx=e.changedTouches[0].clientX-start[0],dy=e.changedTouches[0].clientY-start[1];if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5)imageAt(index+(dx<0?1:-1));start=null},{passive:true});
const slider=document.querySelector('.reach-slider'), slides=[...slider.children], dots=[...document.querySelectorAll('[data-reach-index]')], pause=document.getElementById('slider-pause'), reduced=matchMedia('(prefers-reduced-motion:reduce)');let active=0,paused=reduced.matches,hovering=false,focused=false;
function updatePause(){pause.textContent=paused?'自動再生':'一時停止';pause.setAttribute('aria-label',paused?'自動スライドを開始':'自動スライドを一時停止')}
function moveSlide(i){active=(i+slides.length)%slides.length;const left=slides[active].offsetLeft-slides[0].offsetLeft;slider.scrollTo({left,behavior:reduced.matches?'instant':'smooth'});dots.forEach((dot,n)=>dot.setAttribute('aria-current',String(n===active)))}
pause.addEventListener('click',()=>{paused=!paused;updatePause()});document.querySelectorAll('[data-reach-step]').forEach(b=>b.addEventListener('click',()=>moveSlide(active+Number(b.dataset.reachStep))));dots.forEach(b=>b.addEventListener('click',()=>moveSlide(Number(b.dataset.reachIndex))));slider.addEventListener('mouseenter',()=>hovering=true);slider.addEventListener('mouseleave',()=>hovering=false);slider.addEventListener('focusin',()=>focused=true);slider.addEventListener('focusout',e=>focused=slider.contains(e.relatedTarget));slider.addEventListener('scroll',()=>{const first=slides[0].offsetLeft;let nearest=0;slides.forEach((s,i)=>{if(Math.abs(s.offsetLeft-first-slider.scrollLeft)<Math.abs(slides[nearest].offsetLeft-first-slider.scrollLeft))nearest=i});active=nearest;dots.forEach((b,i)=>b.setAttribute('aria-current',String(i===active)))},{passive:true});setInterval(()=>{if(!paused&&!hovering&&!focused&&!document.hidden&&!dialog.open)moveSlide(active+1)},5500);reduced.addEventListener('change',()=>{paused=reduced.matches;updatePause()});updatePause();
